const supabase=window.BLACKOUT_SUPABASE;
async function supabaseRequest(path,options={}){if(!supabase)throw new Error('Supabase indisponível');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(supabase.url+'/rest/v1/'+path,{...options,signal:controller.signal,headers:{apikey:supabase.publishableKey,Authorization:'Bearer '+supabase.publishableKey,'Content-Type':'application/json',Prefer:'return=representation',...(options.headers||{})}});if(!response.ok)throw new Error('Supabase '+response.status);const body=await response.text();return body?JSON.parse(body):null}finally{clearTimeout(timeout)}}
async function loadProducts(){state.productsLoad='loading';try{const rows=await supabaseRequest('products?select=*&active=eq.true&order=id.asc');if(Array.isArray(rows)){const now=Date.now();products=rows.map(p=>{const promotionActive=Number(p.discount||0)>0&&(!p.promotion_starts_at||new Date(p.promotion_starts_at).getTime()<=now)&&(!p.promotion_ends_at||new Date(p.promotion_ends_at).getTime()>=now);const regularPrice=Number(p.old_price||p.price);const currentPrice=promotionActive?Number(p.price):regularPrice;return{id:Number(p.id),name:p.name,category:p.category,platform:p.platform,price:currentPrice,sku:p.sku||'BIG-'+p.id,old:promotionActive?regularPrice:currentPrice,discount:promotionActive?Number(p.discount||0):0,image:(typeof p.image_url==='string'&&p.image_url.trim())||demoProductImages[Number(p.id)]||null,icon:p.icon||'🎮',glow:p.glow||'#ff641e',stock:Number(p.stock||0),brand:p.brand||'',rating:p.rating==null?null:Number(p.rating),desc:p.description||''}});state.productsLoad='ready'}}catch(error){state.productsLoad='error';console.warn('Catálogo indisponível:',error.message)}finally{if(state.productsLoad==='loading')state.productsLoad='error';if(['home','catalog','offers','product'].includes(state.route))render();if(document.querySelector('#search-panel.open'))document.querySelector('#global-search').dispatchEvent(new Event('input',{bubbles:true}))}}
async function loadStorefrontCategories(){state.categoriesLoad='loading';try{const rows=await supabaseRequest('categories?select=name,icon&active=eq.true&order=sort_order.asc,name.asc');if(Array.isArray(rows)){storefrontCategories=rows.map(item=>item.name);rows.forEach(item=>{if(item.icon&&item.icon!=='◇')categoryIcons[item.name]=item.icon});state.categoriesLoad='ready'}}catch(error){state.categoriesLoad='error';console.warn('Categorias indisponíveis:',error.message)}finally{if(state.categoriesLoad==='loading')state.categoriesLoad='error';if(state.route==='catalog')render()}}
let servicesLoadSequence=0;
async function loadPublicServices(){const loadId=++servicesLoadSequence;state.servicesLoad='loading';try{const rows=await supabaseRequest('services?select=id,name,model,description,image_url,icon,price_type,price,old_price,promotional_price,starting_price,duration_label,benefits&active=eq.true&order=sort_order.asc,name.asc');if(!Array.isArray(rows))throw new Error('Resposta inválida');if(loadId!==servicesLoadSequence)return;services=rows.map(item=>({id:Number(item.id),icon:item.icon||'⚙',name:item.name,model:item.model||'',desc:item.description||'',image:item.image_url||'',priceType:item.price_type||'normal',price:Number(item.price||0),oldPrice:Number(item.old_price||0),promoPrice:Number(item.promotional_price||0),startingPrice:Number(item.starting_price||0),time:item.duration_label||'',benefits:Array.isArray(item.benefits)?item.benefits.filter(Boolean):[]}));state.servicesLoad='ready'}catch(error){if(loadId!==servicesLoadSequence)return;services=fallbackServices;state.servicesLoad='error';console.warn('Serviços indisponíveis:',error.message)}finally{if(loadId!==servicesLoadSequence)return;if(state.route==='services')render();if(document.querySelector('#search-panel.open'))document.querySelector('#global-search').dispatchEvent(new Event('input',{bubbles:true}))}}
async function loadStorefrontBanners(){const previous=JSON.stringify(storefrontBanners);try{const rows=await supabaseRequest('banners?select=id,eyebrow,title,subtitle,image_url,link_label,link_url,sort_order,starts_at,ends_at,created_at&active=eq.true&order=sort_order.asc,created_at.desc');const now=Date.now();storefrontBanners=Array.isArray(rows)?rows.filter(item=>bannerImageUrl(item.image_url)&&(!item.starts_at||new Date(item.starts_at).getTime()<=now)&&(!item.ends_at||new Date(item.ends_at).getTime()>=now)).slice(0,3).map(item=>{const source=bannerImageUrl(item.image_url);return failedBannerUrls.has(source)&&failedBannerUrls.get(source)>=now?null:item}):[]}catch(error){storefrontBanners=[];console.warn('Banners indisponíveis; mantendo artes locais:',error.message)}finally{if(JSON.stringify(storefrontBanners)!==previous&&['home','catalog','offers'].includes(state.route))render()}}
function settingText(value,fallback=''){const text=typeof value==='string'?value.trim():'';return text||fallback}
function contactDigits(value,fallback){const digits=String(value||'').replace(/\D/g,'');if(digits.length>=12&&digits.length<=15)return digits;if(digits.length===10||digits.length===11)return '55'+digits;return fallback}
function normalizeStoreSettings(value={}){const fallbackWhatsapp=contactDigits(defaultStoreSettings.whatsapp,'');return {store_name:settingText(value?.store_name,defaultStoreSettings.store_name),support_phone:settingText(value?.support_phone,defaultStoreSettings.support_phone),whatsapp:contactDigits(value?.whatsapp,contactDigits(value?.support_phone,fallbackWhatsapp)),support_email:settingText(value?.support_email),address:settingText(value?.address,defaultStoreSettings.address),business_hours:settingText(value?.business_hours,defaultStoreSettings.business_hours),instagram:settingText(value?.instagram),delivery_fee:Math.max(0,Number(value?.delivery_fee)||0),free_shipping_min:Math.max(0,Number(value?.free_shipping_min)||0),delivery_checkout_enabled:value?.delivery_checkout_enabled===true,maintenance_mode:value?.maintenance_mode===true}}
function storeName(){return state.storeSettings.store_name}
function instagramUrl(value){const raw=String(value||'').trim();if(!raw)return '';const handle=raw.replace(/^@/,'');if(/^[a-z0-9._]+$/i.test(handle))return 'https://www.instagram.com/'+handle+'/';try{const url=new URL(raw);return /^https?:$/.test(url.protocol)&&/(^|\.)instagram\.com$/i.test(url.hostname)?url.href:''}catch{return ''}}
function updateStoreStructuredData(){let node=document.querySelector('#store-structured-data');if(!node){node=document.createElement('script');node.id='store-structured-data';node.type='application/ld+json';document.head.appendChild(node)}const settings=state.storeSettings;const data={'@context':'https://schema.org','@type':'Store',name:settings.store_name,telephone:settings.support_phone,email:settings.support_email||undefined,address:settings.address,openingHours:settings.business_hours,sameAs:instagramUrl(settings.instagram)||undefined};node.textContent=JSON.stringify(data)}
function applyStoreSettings(){const name=storeName();const parts=name.split(/\s+/);const primary=parts.shift()||defaultStoreSettings.store_name.split(' ')[0];const secondary=parts.join(' ');const brand=document.querySelector('.brand-wordmark');if(brand){brand.querySelector('strong').textContent=primary;brand.querySelector('span').textContent=secondary;brand.setAttribute('aria-label',name+' — ir para o início')}const drawerBrand=document.querySelector('.drawer-head span');if(drawerBrand)drawerBrand.textContent=name;document.title=name;const description=document.querySelector('meta[name="description"]');if(description)description.content=name+' — jogos, acessórios, consoles e serviços gamer.';updateStoreStructuredData()}
async function loadStoreSettings(){const previous=JSON.stringify(state.storeSettings);try{const rows=await window.BlackoutCommerce.settings();state.storeSettings=normalizeStoreSettings(Array.isArray(rows)?rows[0]:null)}catch(error){state.storeSettings=normalizeStoreSettings(state.storeSettings);console.warn('Configurações da loja indisponíveis; mantendo valores seguros:',error.message)}finally{applyStoreSettings();if(JSON.stringify(state.storeSettings)!==previous)render()}}
function bannerImageUrl(value){const raw=String(value||'').trim();if(!raw)return '';if(raw.startsWith('/storage/v1/'))return supabase.url+raw;if(raw.startsWith('storage/v1/'))return supabase.url+'/'+raw;try{const url=new URL(raw,location.href);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}
function bannerLink(value){const raw=String(value||'').trim();const route=/^#(home|catalog|services|offers|favorites)$/.exec(raw);if(route)return {href:raw,route:route[1]};if(!/^https?:\/\//i.test(raw)&&!raw.startsWith('//'))return null;try{const url=new URL(raw,location.href);if(['http:','https:'].includes(url.protocol))return {href:url.href,external:true}}catch{}return null}
function bannerImage(slot,fallback,alt,width,height,extra=''){const banner=storefrontBanners[slot];const src=bannerImageUrl(banner?.image_url);const description=src?[banner.title,banner.subtitle].filter(Boolean).join('. '):alt;const managed=src?` style="aspect-ratio:${width}/${height};object-fit:cover" data-banner-slot="${slot}" data-banner-fallback="${html(fallback)}" data-banner-fallback-alt="${html(alt)}"`:'';return `<img src="${html(src||fallback)}" alt="${html(description)}" width="${width}" height="${height}"${managed} ${extra}>`}
function bannerAnchor(banner,fallbackRoute,fallbackLabel,fallbackCategory=''){const link=banner&&bannerLink(banner.link_url);if(!link)return `href="#${fallbackRoute}" ${fallbackCategory?`data-category="${fallbackCategory}"`:`data-route="${fallbackRoute}"`} aria-label="${html(fallbackLabel)}"`;return `href="${html(link.href)}" ${link.route?`data-route="${link.route}"`:'target="_blank" rel="noopener noreferrer"'} aria-label="${html(banner.link_label||banner.title||fallbackLabel)}"`}
function bindBannerFallbacks(root){root.querySelectorAll('img[data-banner-fallback]').forEach(img=>{const recover=()=>{if(img.dataset.bannerRecovered)return;img.dataset.bannerRecovered='true';failedBannerUrls.set(img.src,Date.now()+300000);img.src=img.dataset.bannerFallback;img.alt=img.dataset.bannerFallbackAlt;img.style.aspectRatio='';img.style.objectFit='';storefrontBanners[Number(img.dataset.bannerSlot)]=null;queueMicrotask(()=>{if(['home','catalog','offers'].includes(state.route))render()})};img.addEventListener('error',recover,{once:true});if(img.complete&&!img.naturalWidth)recover()})}
async function createOrder(){
  const data=state.checkoutData;
  if(!state.checkoutAttempt)state.checkoutAttempt=crypto.randomUUID();
  const items=Object.entries(state.cart).map(([id,quantity])=>({product_id:Number(id),quantity:Number(quantity)}));
  if(!items.length)throw new Error('Seu carrinho está vazio.');
  const address=data.deliveryMethod==='entrega'?{cep:data.cep,street:data.street,number:data.number,complement:data.complement,neighborhood:data.neighborhood,city:data.city,state:data.state,reference:data.reference}:null;
  const order=await window.BlackoutCommerce.place(items,state.coupon||null,data.deliveryMethod,data.paymentMethod,{name:data.name,email:data.email,phone:data.phone},address,state.checkoutAttempt,state.quote?.total);
  state.lastOrder=order;
  localStorage.setItem('blackout-last-order',JSON.stringify(order));
  return order;
}
const html=value=>String(value??'').replace(/[&<>\"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const save=()=>{localStorage.setItem('blackout-cart',JSON.stringify(state.cart));localStorage.setItem('blackout-favorites',JSON.stringify(state.favorites));updateCart()};
const updateCart=()=>{const badge=document.querySelector('.cart-count');const next=Object.values(state.cart).reduce((a,b)=>a+b,0);const changed=badge.textContent!==String(next);badge.textContent=next;if(changed&&touchUI()){badge.classList.remove('cart-bump');void badge.offsetWidth;badge.classList.add('cart-bump');setTimeout(()=>badge.classList.remove('cart-bump'),260)}};
const toast=msg=>{const t=document.querySelector('#toast');clearTimeout(toastTimer);t.textContent=msg;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),1800)};
function enhanceImages(root=document){root.querySelectorAll('img').forEach(img=>{const productId=img.dataset.productId||img.closest('.product-card [data-product]')?.dataset.product;const fallback=demoProductImages[Number(productId)];if(fallback&&img.getAttribute('src')!==fallback){const recover=()=>{if(img.getAttribute('src')!==fallback)img.src=fallback};img.addEventListener('error',recover,{once:true});if(img.complete&&!img.naturalWidth)recover()}img.classList.add('media-fade');const reveal=()=>{img.classList.add('is-loaded');img.closest('.hero')?.classList.add('hero-ready')};if(img.complete)reveal();else{img.addEventListener('load',reveal,{once:true});img.addEventListener('error',reveal,{once:true});img.decode?.().then(reveal,()=>{if(img.complete)reveal()});setTimeout(()=>{if(img.isConnected&&img.complete)reveal()},1200)}})}
function animatePageIn(){if(!touchUI()||reducedMotion())return;app.classList.remove('page-enter');void app.offsetWidth;app.classList.add('page-enter');setTimeout(()=>app.classList.remove('page-enter'),240)}
function skeletonCards(count){return '<div class="product-grid catalog-products skeleton-grid" aria-label="Carregando produtos">'+Array.from({length:count},()=>'<div class="skeleton-card"><span class="skeleton-image"></span><span class="skeleton-line"></span><span class="skeleton-line short"></span><span class="skeleton-button"></span></div>').join('')+'</div>'}
function skeletonProduct(){return '<section class="detail section product-skeleton" aria-label="Carregando produto"><span class="skeleton-image"></span><div><span class="skeleton-line"></span><span class="skeleton-line short"></span><span class="skeleton-line"></span><span class="skeleton-button"></span></div></section>'}
function card(p){const visual=p.image?`<img src="${html(p.image)}" alt="${html(p.name)}" loading="lazy" decoding="async">`:`<span class="product-fallback">${html(p.icon)}</span>`;const soldOut=Number(p.stock)<=0;const tone=Number(p.id)===5?"playstation":Number(p.id)===6?"xbox":"default";const platform=Number(p.id)===5?"PS5":Number(p.id)===6?"XBOX":p.platform;const type=Number(p.id)===5?"Esporte":Number(p.id)===6?"Ação":p.category;return `<article class="product-card platform-${tone}" style="--product-glow:${html(p.glow)}">${p.discount>0?`<span class="badge">-${Number(p.discount)}%</span>`:""}<button class="favorite ${state.favorites.includes(p.id)?"on":""}" data-favorite="${Number(p.id)}" aria-label="Favoritar ${html(p.name)}">${state.favorites.includes(p.id)?"♥":"♡"}</button><div class="product-visual ${p.image?"has-image":""}" data-product="${Number(p.id)}">${visual}</div><div class="product-info"><small class="product-platform">${html(platform)}</small><h3>${html(p.name)}</h3><p class="product-meta">${html(type)} <i></i> ${html(p.brand||"BLACKOUT")}</p><div class="price">${money(p.price)}</div>${p.old>p.price?`<div class="old-price">${money(p.old)}</div>`:"<div class=\"old-price placeholder\">&nbsp;</div>"}<div class="card-actions"><button class="buy" data-add="${Number(p.id)}" ${soldOut?"disabled":""}><span>⌑</span>${soldOut?"Sem estoque":"Comprar"}</button><button class="details" data-product="${Number(p.id)}" aria-label="Ver detalhes de ${html(p.name)}">›</button></div></div></article>`}
function home(){const settings=state.storeSettings;const name=storeName();const contact=[name,settings.address,'Atendimento: '+settings.business_hours,'Telefone: '+settings.support_phone,settings.support_email&&'E-mail: '+settings.support_email,settings.instagram&&'Instagram: '+settings.instagram].filter(Boolean).join('. ');const mapUrl='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(settings.address);const whatsappUrl='https://wa.me/'+settings.whatsapp;return `<section class="hero home-reference-hero" aria-label="Destaques ${html(name)}">${bannerImage(0,'./assets/blackout-home-hero.png',name+'. Mais que jogos, uma paixão. Consoles, jogos e acessórios gamer.',958,1641,'fetchpriority="high" decoding="async"')}<a class="home-reference-cta" ${bannerAnchor(storefrontBanners[0],'catalog','Explore o universo gamer: abrir catálogo')}></a></section>

<section class="section interactive-showcase" aria-label="Explore a ${html(name)}"><div class="category-panel-top"><img src="./assets/blackout-category-top.png" width="1098" height="956" loading="lazy" alt=""><a href="#catalog" class="panel-hotspot panel-games" data-category="Jogos" aria-label="Abrir Jogos"></a><a href="#catalog" class="panel-hotspot panel-accessories" data-category="Acessórios" aria-label="Abrir Acessórios"></a><a href="#catalog" class="panel-hotspot panel-consoles" data-category="Consoles" aria-label="Abrir Consoles"></a><a href="#services" class="panel-hotspot panel-services" data-category="Serviços" aria-label="Abrir Serviços"></a><a href="#offers" class="panel-hotspot panel-offers" data-category="Ofertas" aria-label="Abrir Ofertas"></a></div><div class="category-panel-launch">${bannerImage(1,'./assets/blackout-launch-exact.png',name+': lançamentos em jogos',1900,828,'loading="lazy"')}<a ${bannerAnchor(storefrontBanners[1],'catalog','Ver lançamentos em jogos','Jogos')} class="panel-hotspot panel-launch"></a></div></section>

<section class="section location-showcase" aria-label="Localização e atendimento da ${html(name)}" title="${html(contact)}" data-support-email="${html(settings.support_email)}" data-instagram="${html(settings.instagram)}"><img src="./assets/blackout-location-contact-new.png" width="1224" height="1285" loading="lazy" alt="${html(contact)}"><a class="location-map" href="${html(mapUrl)}" target="_blank" rel="noopener" aria-label="Abrir ${html(settings.address)} no Google Maps" title="Abrir endereço no Google Maps"></a><a class="location-whatsapp" href="${html(whatsappUrl)}" target="_blank" rel="noopener" aria-label="Conversar com a ${html(name)} pelo WhatsApp: ${html(settings.support_phone)}" title="Conversar pelo WhatsApp"></a></section>`}
function catalogList(offers=false){let list=state.filter==='Todos'?products:products.filter(p=>p.category===state.filter);if(offers||state.catalogOnlyDiscount)list=list.filter(p=>p.discount>0);if(state.catalogOnlyStock)list=list.filter(p=>Number(p.stock)>0);const query=state.catalogSearch.trim().toLocaleLowerCase('pt-BR');if(query)list=list.filter(p=>[p.name,p.brand,p.category,p.platform].some(value=>String(value||'').toLocaleLowerCase('pt-BR').includes(query)));if(state.catalogSort==='price-asc')list=[...list].sort((a,b)=>a.price-b.price);if(state.catalogSort==='price-desc')list=[...list].sort((a,b)=>b.price-a.price);if(state.catalogSort==='discount')list=[...list].sort((a,b)=>b.discount-a.discount);return list}
function catalogResultsMarkup(offers=false){if(state.productsLoad==='loading')return skeletonCards(4);const list=catalogList(offers);return `<div class="catalog-result-head"><span><strong>${list.length}</strong> ${list.length===1?'item encontrado':'itens encontrados'}</span><div class="catalog-view-switch" aria-label="Modo de visualização"><button class="${state.catalogView==='grid'?'active':''}" data-catalog-view="grid" aria-label="Visualização em grade">▦</button><button class="${state.catalogView==='list'?'active':''}" data-catalog-view="list" aria-label="Visualização em lista">☷</button><button class="${state.catalogView==='compact'?'active':''}" data-catalog-view="compact" aria-label="Visualização compacta">▥</button></div></div>${list.length?`<div class="product-grid catalog-products ${state.catalogView}">${list.map(card).join('')}</div>`:'<div class="catalog-empty"><span>⌕</span><h2>Nenhum produto encontrado</h2><p>Tente outra busca ou selecione uma categoria diferente.</p></div>'}`}
function renderCatalogResults(offers=false){const node=document.querySelector('#catalog-results');if(!node)return;node.innerHTML=catalogResultsMarkup(offers);bind();enhanceImages(node)}
function catalog(offers=false){const filters=['Todos',...new Set([...storefrontCategories,'Cartões'])];return `<section class="catalog-page"><section class="catalog-hero catalog-hero-art" aria-label="Catálogo BLACKOUT Infor Games"><h1 class="catalog-hero-title">Catálogo BLACKOUT Infor Games</h1>${bannerImage(2,'./assets/blackout-catalog-hero-new.png','Consoles, jogos e acessórios gamer com a identidade BLACKOUT Infor Games',1609,977,'decoding="async" fetchpriority="high"')}${storefrontBanners[2]&&bannerLink(storefrontBanners[2].link_url)?`<a ${bannerAnchor(storefrontBanners[2],'catalog','Abrir destaque do catálogo')} style="position:absolute;inset:0;z-index:2"></a>`:''}</section><div class="catalog-filter-row" aria-label="Categorias">${filters.map(name=>`<button class="catalog-chip ${state.filter===name?'active':''}" data-filter="${name}"><span>${name==='Todos'?'▦':categoryIcons[name]||'◇'}</span>${name}</button>`).join('')}</div><div class="catalog-tools"><label class="catalog-search"><span>⌕</span><input data-catalog-search type="search" value="${state.catalogSearch}" placeholder="Buscar jogos, consoles, acessórios..." aria-label="Buscar no catálogo"></label><select data-catalog-sort aria-label="Ordenar produtos"><option value="relevance" ${state.catalogSort==='relevance'?'selected':''}>Mais relevantes</option><option value="price-asc" ${state.catalogSort==='price-asc'?'selected':''}>Menor preço</option><option value="price-desc" ${state.catalogSort==='price-desc'?'selected':''}>Maior preço</option><option value="discount" ${state.catalogSort==='discount'?'selected':''}>Maior desconto</option></select><button class="catalog-filter-button" type="button" data-action="catalog-filter">▽ <span>Filtros</span></button></div><div class="catalog-advanced" id="catalog-advanced" hidden><button data-quick-filter="discount" class="${state.catalogOnlyDiscount?'active':''}">％ Com desconto</button><button data-quick-filter="stock" class="${state.catalogOnlyStock?'active':''}">● Em estoque</button></div><div id="catalog-results">${catalogResultsMarkup(offers)}</div><section class="catalog-benefits"><article><span>▣</span><div><strong>ENTREGA DIGITAL</strong><small>Receba na hora</small></div></article><article><span>◇</span><div><strong>COMPRA SEGURA</strong><small>Seus dados protegidos</small></div></article><article><span>◉</span><div><strong>SUPORTE ESPECIALIZADO</strong><small>Atendimento via WhatsApp</small></div></article><article><span>⌑</span><div><strong>OFERTAS EXCLUSIVAS</strong><small>Jogos com até 70% off</small></div></article></section></section>`}
function product(){if(state.productsLoad==='loading')return skeletonProduct();const p=products.find(x=>x.id===state.selected)||products[0];const visual=p.image?`<img src="${p.image}" alt="${p.name}" data-product-id="${p.id}">`:p.icon;setWhats(`Olá! Gostaria de informações sobre ${p.name}.`);return `<button class="link-btn" data-route="catalog">← Voltar ao catálogo</button><section class="detail section"><div class="detail-art ${p.image?'has-image':''}">${visual}</div><div><span class="eyebrow">${p.brand} • ${p.platform}</span><h1>${p.name}</h1>${p.rating?`<div class="rating">★★★★★ <small>${p.rating} (128 avaliações)</small></div>`:''}<p>${p.desc}</p>${p.old>p.price?`<div class="old-price">${money(p.old)}</div>`:''}<div class="price">${money(p.price)}</div><p>ou 10x de <strong>${money(p.price/10)}</strong> sem juros</p><p class="stock">● Em estoque — ${p.stock} unidades</p><div class="qty"><button data-qty="-1">−</button><span id="detail-qty">${state.detailQty}</span><button data-qty="1">+</button></div><div class="detail-actions"><button class="primary" data-buy-now="${p.id}">Comprar agora</button><button class="secondary" data-add="${p.id}">Adicionar ao carrinho</button></div><div class="tabs"><h2>Descrição e especificações</h2><div class="specs"><span>✓ Garantia de 12 meses</span><span>✓ Nota fiscal</span><span>✓ Produto original</span><span>✓ Envio para todo Brasil</span></div></div></div></section>`}
function cart(){const items=Object.entries(state.cart).map(([id,q])=>({p:products.find(x=>x.id===+id),q})).filter(x=>x.p);const sub=items.reduce((a,x)=>a+x.p.price*x.q,0);return `<div class="page-head"><div><h1 class="page-title">SEU CARRINHO</h1><p class="page-sub">Revise seus itens antes de avançar.</p></div></div>${items.length?`<div class="cart-layout"><div>${items.map(({p,q})=>`<div class="cart-item"><div class="mini-art">${p.icon}</div><div><strong>${p.name}</strong><div class="price">${money(p.price)}</div><div class="qty"><button data-cart-qty="${p.id}:-1">−</button><span>${q}</span><button data-cart-qty="${p.id}:1">+</button></div></div><button class="remove" data-remove="${p.id}">Remover</button></div>`).join('')}</div><aside class="summary"><h2>Resumo</h2><div class="coupon"><input placeholder="Cupom de desconto"><button data-coupon>Aplicar</button></div><div class="summary-row"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Entrega</span><b>Grátis</b></div><div class="summary-row total"><span>Total</span><span>${money(sub)}</span></div><button class="primary" data-route="checkout" style="width:100%">Finalizar compra</button></aside></div>`:`<div class="empty"><h2>Seu carrinho está vazio</h2><p>Explore o catálogo e prepare seu próximo upgrade.</p><button class="primary" data-route="catalog">Ver catálogo</button></div>`}`}
function checkout(){const steps=['Dados','Endereço','Entrega','Pagamento','Revisão','Confirmado'];if(!Object.keys(state.cart).length&&state.checkoutStep<6)return `<div class="empty"><h1>Seu carrinho está vazio</h1><p>Adicione um produto para continuar.</p><button class="primary" data-route="catalog">Ver catálogo</button></div>`;return `<div class="page-head"><div><h1 class="page-title">CHECKOUT SEGURO</h1><p class="page-sub">Etapa ${state.checkoutStep} de 6</p></div></div><div class="checkout-steps">${steps.map((name,index)=>`<div class="step ${index+1<=state.checkoutStep?'active':''}">${index+1}. ${name}</div>`).join('')}</div><section class="summary checkout-panel" style="max-width:760px;margin:auto;position:static">${checkoutContent()}<p id="checkout-error" class="checkout-error" role="alert" hidden></p><div class="detail-actions" style="margin-top:22px">${state.checkoutStep>1&&state.checkoutStep<6?'<button class="secondary" data-checkout="prev">Voltar</button>':''}${state.checkoutStep<6?`<button class="primary" data-checkout="next">${state.checkoutStep===5?'Confirmar pedido':'Continuar'}</button>`:'<button class="primary" data-route="orders">Acompanhar pedido</button>'}</div></section>`}
function checkoutContent(){const data=state.checkoutData;const field=(key,label,type='text',extra='')=>`<div class="form-field"><label for="co-${key}">${label}</label><input id="co-${key}" data-checkout-field="${key}" type="${type}" value="${html(data[key]||'')}" ${extra}></div>`;if(state.checkoutStep===1)return `<h2>Dados do cliente</h2><div class="form-grid">${field('name','Nome completo','text','autocomplete="name" required')}${field('email','E-mail','email','autocomplete="email" required')}${field('phone','Telefone','tel','autocomplete="tel" inputmode="tel" placeholder="(00) 00000-0000" required')}${field('cpf','CPF','text','inputmode="numeric" placeholder="000.000.000-00" required')}</div>`;if(state.checkoutStep===2)return `<h2>Endereço</h2><div class="form-grid">${field('cep','CEP','text','inputmode="numeric" autocomplete="postal-code" placeholder="00000-000"')}${field('city','Cidade','text','autocomplete="address-level2"')}${field('street','Rua','text','autocomplete="street-address"')}${field('number','Número','text','autocomplete="off"')}</div>`;if(state.checkoutStep===3)return `<h2>Como você quer receber?</h2><div class="menu-list checkout-choices"><button type="button" data-checkout-choice="delivery:entrega" aria-pressed="${data.deliveryMethod==='entrega'}" class="${data.deliveryMethod==='entrega'?'selected':''}">🚚 Entrega expressa <b>Grátis</b></button><button type="button" data-checkout-choice="delivery:retirada" aria-pressed="${data.deliveryMethod==='retirada'}" class="${data.deliveryMethod==='retirada'?'selected':''}">🏪 Retirada na loja <b>Hoje</b></button></div>`;if(state.checkoutStep===4)return `<h2>Pagamento</h2><div class="menu-list checkout-choices"><button type="button" data-checkout-choice="payment:pix" aria-pressed="${data.paymentMethod==='pix'}" class="${data.paymentMethod==='pix'?'selected':''}">◈ PIX <b>5% de desconto</b></button><button type="button" data-checkout-choice="payment:cartao" aria-pressed="${data.paymentMethod==='cartao'}" class="${data.paymentMethod==='cartao'?'selected':''}">▰ Cartão de crédito <b>até 10x</b></button></div>`;if(state.checkoutStep===5)return `<h2>Revise seu pedido</h2><p>${html(data.name)} · ${html(data.email)}</p><p>${data.deliveryMethod==='retirada'?'Retirada na loja':`Entrega: ${html(data.street)}, ${html(data.number)} — ${html(data.city)}`}</p><p>Pagamento: ${data.paymentMethod==='pix'?'PIX':'Cartão de crédito'}</p><div class="summary-row total"><span>Total dos produtos</span><span>${money(Object.entries(state.cart).reduce((sum,[id,quantity])=>sum+(products.find(item=>item.id===Number(id))?.price||0)*quantity,0))}</span></div>`;return `<div class="empty"><h2>✓ Pedido recebido!</h2><p>Seu pedido foi enviado à BLACKOUT. Acompanhe os próximos passos com a loja.</p></div>`}
function showCheckoutError(message,field){const node=document.querySelector('#checkout-error');if(node){node.textContent=message;node.hidden=false}if(field)document.querySelector(`[data-checkout-field="${field}"]`)?.focus();return false}
function validCpf(value){const digits=String(value||'').replace(/\D/g,'');if(digits.length!==11||/^(\d)\1{10}$/.test(digits))return false;for(let size=9;size<11;size++){let sum=0;for(let i=0;i<size;i++)sum+=Number(digits[i])*(size+1-i);let digit=(sum*10)%11;if(digit===10)digit=0;if(digit!==Number(digits[size]))return false}return true}
function validateCheckoutStep(){const data=state.checkoutData;if(state.checkoutStep===1){if(String(data.name||'').trim().length<2)return showCheckoutError('Informe seu nome completo.','name');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(data.email||'').trim()))return showCheckoutError('Informe um e-mail válido.','email');const phone=String(data.phone||'').replace(/\D/g,'');if(phone.length<10||phone.length>11)return showCheckoutError('Informe um telefone válido.','phone');if(!validCpf(data.cpf))return showCheckoutError('Informe um CPF válido.','cpf')}if(state.checkoutStep===3){if(!data.deliveryMethod)return showCheckoutError('Escolha entrega ou retirada.');if(data.deliveryMethod==='entrega'){const address=String(data.cep||'').replace(/\D/g,'').length===8&&String(data.city||'').trim()&&String(data.street||'').trim()&&String(data.number||'').trim();if(!address){state.checkoutStep=2;render();return showCheckoutError('Preencha o endereço completo para entrega.','cep')}}}if(state.checkoutStep===4&&!data.paymentMethod)return showCheckoutError('Escolha uma forma de pagamento.');return true}
function serviceAsset(value){const raw=String(value||'').trim();return raw&&!/^javascript:/i.test(raw)?raw:''}
function serviceRequestName(service){return [service.name,service.model].filter(Boolean).join(' ')}
function servicePriceMarkup(service){
 if(service.priceType==='sale')return `<div class='service-price service-price-sale'><span>DE <del>${money(service.oldPrice)}</del></span><b>POR <strong>${money(service.promoPrice)}</strong></b></div>`;
 if(service.priceType==='starting_at')return `<div class='service-price'><span>A PARTIR DE</span><strong>${money(service.startingPrice)}</strong></div>`;
 if(service.priceType==='consult')return `<div class='service-price service-price-consult'><strong>PREÇO SOB CONSULTA</strong></div>`;
 return `<div class='service-price'><span>PREÇO</span><strong>${money(service.price)}</strong></div>`;
}
function servicesView(){
 setWhats('Olá! Gostaria de solicitar um serviço técnico na '+storeName()+'.');
 const skeleton=`<article class='service-card service-skeleton' aria-hidden='true'><div class='service-media'></div><div class='service-body'><i></i><i></i><i></i></div></article>`;
 const cards=services.map((service,index)=>{const image=serviceAsset(service.image);const requestName=serviceRequestName(service);return `<article class='service-card service-tone-${index%2?'blue':'orange'}'><div class='service-media'>${image?`<img src='${html(image)}' width='900' height='1125' loading='lazy' alt='${html(requestName)}'>`:`<span class='service-icon'>${html(service.icon)}</span>`}<span class='service-media-shade'></span></div><div class='service-body'><div class='service-heading'><h3>${html(service.name)}</h3>${service.model?`<span>${html(service.model)}</span>`:''}</div><p>${html(service.desc)}</p>${service.benefits.length?`<ul class='service-benefits'>${service.benefits.map(item=>`<li>${html(item)}</li>`).join('')}</ul>`:''}<div class='service-card-bottom'>${servicePriceMarkup(service)}${service.time?`<small class='service-time'>Prazo: ${html(service.time)}</small>`:''}<button class='service-request' data-service='${html(requestName)}'><span aria-hidden='true'>◆</span> SOLICITAR SERVIÇO</button></div></div></article>`}).join('');
 const content=state.servicesLoad==='loading'?Array.from({length:4},()=>skeleton).join(''):cards||(state.servicesLoad==='error'?`<div class='empty service-empty'><h2>Serviços temporariamente indisponíveis</h2><p>Não foi possível atualizar o catálogo agora. Tente novamente em instantes.</p><button class='secondary' data-retry-services>Tentar novamente</button></div>`:`<div class='empty service-empty'><h2>Nenhum serviço disponível</h2><p>Novos serviços serão publicados aqui pela loja.</p></div>`);
 return `<section class='services-page'><header class='services-hero'><span class='eyebrow'>ASSISTÊNCIA TÉCNICA ESPECIALIZADA</span><h1>Serviços para seu <em>game voltar ao jogo</em></h1><p>Atendimento técnico com cuidado, transparência e a identidade BLACKOUT.</p></header><div class='service-grid'>${content}</div></section>`;
}
function orders(){return `<div class="page-head"><div><h1 class="page-title">PEDIDO #BK-1048</h1><p class="page-sub">Previsão de entrega: 18 de setembro</p></div><span class="status-pill">Em preparação</span></div><section class="summary" style="position:static;max-width:700px"><div class="timeline">${[['Pedido recebido','15 set • 10:32'],['Pagamento confirmado','15 set • 10:34'],['Preparando','Seu pedido está sendo separado'],['Enviado','Aguardando'],['Entregue','Aguardando']].map((x,i)=>`<div class="timeline-item ${i<3?'done':''}"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section>`}
function profile(){return `<div class="profile-card"><div class="avatar">👤</div><div><h2 style="margin:0">Alex Gamer</h2><p style="margin:5px 0;color:#91a1ab">alex@email.com</p></div><button class="secondary">Editar</button></div><div class="menu-list"><button data-route="orders">Meus pedidos <span>›</span></button><button data-route="favorites">Meus favoritos <span>›</span></button><button>Meus endereços <span>›</span></button><button>Cupons <span>›</span></button><button>Notificações <span>›</span></button><button>Configurações <span>›</span></button><button data-action="login">Entrar ou criar conta <span>›</span></button></div>`}
function favorites(){const list=products.filter(p=>state.favorites.includes(p.id));return `<div class="page-head"><div><h1 class="page-title">MEUS FAVORITOS</h1><p class="page-sub">Produtos que você guardou.</p></div></div>${list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:'<div class="empty"><h2>Nenhum favorito ainda</h2><p>Toque no coração dos produtos para guardar aqui.</p></div>'}`}
function maintenanceView(){const name=storeName();const settings=state.storeSettings;return `<div class="empty"><h1>${html(name)} está em manutenção</h1><p>Estamos preparando a loja para receber você novamente.</p><a class="secondary" href="https://wa.me/${html(settings.whatsapp)}" target="_blank" rel="noopener">Falar com a loja</a></div>`}
function render(options={}){applyStoreSettings();setWhats('Olá! Gostaria de atendimento na '+storeName()+'.');const active=options.resetScroll?null:document.activeElement;const focused=active?.dataset?.checkoutField||(active?.id==='cart-coupon'?'cart-coupon':null);const inputValue=focused?active.value:null;const caret=focused?active.selectionStart:null;const views={home:home,catalog:()=>catalog(false),offers:()=>catalog(true),product,cart,checkout,services:servicesView,orders,profile,favorites};const maintenance=state.storeSettings.maintenance_mode===true;app.innerHTML=maintenance?maintenanceView():(views[state.route]||home)();if(!maintenance&&(state.productsLoad==='error'||state.categoriesLoad==='error')&&['catalog','offers','product'].includes(state.route))app.insertAdjacentHTML('afterbegin','<div class="connection-notice" role="alert"><span>Não foi possível atualizar o catálogo. Preços e estoque exibidos podem estar desatualizados.</span><button type="button" data-retry-catalog>Tentar novamente</button></div>');bind();app.querySelector('[data-retry-catalog]')?.addEventListener('click',()=>{state.productsLoad='loading';state.categoriesLoad='loading';render();loadProducts();loadStorefrontCategories()});bindBannerFallbacks(app);enhanceImages(app);if(focused&&!maintenance){const field=focused==='cart-coupon'?app.querySelector('#cart-coupon'):app.querySelector('[data-checkout-field="'+focused+'"]');if(field){if(focused==='cart-coupon')field.value=inputValue;field.focus({preventScroll:true});if(caret!=null&&field.setSelectionRange)try{field.setSelectionRange(caret,caret)}catch{}}}if(options.resetScroll){app.focus({preventScroll:true});window.scrollTo(0,0);animatePageIn()}}
function go(route){if(route==='product')state.detailQty=1;if(route===state.route){closePanels();window.scrollTo({top:0,behavior:'smooth'});if(route==='services')loadPublicServices();return}const previous=history.state||{};history.replaceState({...previous,route:state.route,selected:state.selected,scrollY:window.scrollY},'',location.href);state.route=route;history.pushState({route,selected:state.selected,scrollY:0,depth:Number(previous.depth||0)+1},'','#'+route);closePanels();render({resetScroll:true});if(route==='services')loadPublicServices()}
function setWhats(msg){const link=document.querySelector('#whatsapp');if(link)link.href=`https://wa.me/${state.storeSettings.whatsapp}?text=${encodeURIComponent(msg)}`}
function closePanels(){const drawer=document.querySelector('#drawer');const backdrop=document.querySelector('#backdrop');const search=document.querySelector('#search-panel');if(search.contains(document.activeElement))document.activeElement.blur();drawer.classList.remove('open');backdrop.classList.remove('open');search.classList.remove('open');document.documentElement.classList.remove('menu-open');drawer.setAttribute('aria-hidden','true');search.setAttribute('aria-hidden','true')}
window.blackoutHandleBack=()=>{const dialog=document.querySelector('dialog[open]');if(dialog){dialog.close();return true}if(document.querySelector('#search-panel.open,#drawer.open')){closePanels();return true}if(document.documentElement.classList.contains('keyboard-open')&&document.activeElement?.matches?.('input,textarea,select')){document.activeElement.blur();return true}if(state.route==='checkout'&&state.checkoutStep>1&&state.checkoutStep<6){state.checkoutStep--;render();return true}if(state.route!=='home'){if(Number(history.state?.depth||0)>0)history.back();else{state.route='home';history.replaceState({route:'home',selected:state.selected,scrollY:0,depth:0},'','#home');render({resetScroll:true})}return true}return false};
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const searchOpen=document.querySelector('#search-panel').classList.contains('open');const drawerOpen=document.querySelector('#drawer').classList.contains('open');if(!searchOpen&&!drawerOpen)return;event.preventDefault();closePanels();document.querySelector(searchOpen?'[data-action=\"search\"]':'[data-action=\"menu\"]')?.focus()});
function addToCart(id,quantity=1){const product=products.find(item=>item.id===id);if(!product||!Number.isInteger(quantity)||quantity<1)return false;const next=Number(state.cart[id]||0)+quantity;if(next>Number(product.stock)){toast('Quantidade indisponível no estoque');return false}state.cart[id]=next;save();return true}
function bind(){document.querySelectorAll('[data-route]').forEach(e=>e.onclick=ev=>{ev.preventDefault();go(e.dataset.route)});document.querySelectorAll('[data-category]').forEach(e=>e.onclick=ev=>{ev.preventDefault();const c=e.dataset.category;if(c==='Serviços')go('services');else if(c==='Ofertas')go('offers');else{state.filter=c;go('catalog')}});document.querySelectorAll('[data-filter]').forEach(e=>e.onclick=()=>{state.filter=e.dataset.filter;render()});document.querySelectorAll('[data-product]').forEach(e=>e.onclick=()=>{state.selected=+e.dataset.product;go('product')});document.querySelectorAll('[data-qty]').forEach(e=>e.onclick=()=>{const product=products.find(item=>item.id===state.selected)||products[0];state.detailQty=Math.max(1,Math.min(Number(product.stock)||1,state.detailQty+Number(e.dataset.qty)));document.querySelector('#detail-qty').textContent=state.detailQty});document.querySelectorAll('[data-add]').forEach(e=>e.onclick=()=>{if(addToCart(+e.dataset.add,state.route==='product'?state.detailQty:1))toast('Produto adicionado ao carrinho')});document.querySelectorAll('[data-buy-now]').forEach(e=>e.onclick=()=>{if(addToCart(+e.dataset.buyNow,state.detailQty)){state.checkoutStep=1;go('checkout')}});document.querySelectorAll('[data-favorite]').forEach(e=>e.onclick=()=>{const id=+e.dataset.favorite;e.classList.add('favorite-pop');setTimeout(()=>{state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(state.route==='catalog'||state.route==='offers')renderCatalogResults(state.route==='offers');else render()},touchUI()&&!reducedMotion()?120:0)});document.querySelectorAll('[data-cart-qty]').forEach(e=>e.onclick=()=>{const [id,d]=e.dataset.cartQty.split(':').map(Number);if(d>0){if(!addToCart(id,1))return}else{state.cart[id]=Number(state.cart[id]||0)-1;if(state.cart[id]<=0)delete state.cart[id];save()}render()});document.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{delete state.cart[e.dataset.remove];save();render()});document.querySelectorAll('[data-checkout-choice]').forEach(e=>e.onclick=()=>{const [kind,value]=e.dataset.checkoutChoice.split(':');state.checkoutData[kind==='delivery'?'deliveryMethod':'paymentMethod']=value;render()});document.querySelectorAll('.service-request').forEach(e=>e.onclick=()=>window.open(`https://wa.me/${state.storeSettings.whatsapp}?text=${encodeURIComponent('Olá! Tenho interesse no serviço de '+e.dataset.service+'.')}`,'_blank','noopener'));document.querySelector('[data-retry-services]')?.addEventListener('click',loadPublicServices);const catalogSearch=document.querySelector('[data-catalog-search]');if(catalogSearch)catalogSearch.oninput=e=>{state.catalogSearch=e.target.value;renderCatalogResults(state.route==='offers')};const catalogSort=document.querySelector('[data-catalog-sort]');if(catalogSort)catalogSort.onchange=e=>{state.catalogSort=e.target.value;renderCatalogResults(state.route==='offers')};document.querySelectorAll('[data-catalog-view]').forEach(e=>e.onclick=()=>{state.catalogView=e.dataset.catalogView;renderCatalogResults(state.route==='offers')});document.querySelectorAll('[data-quick-filter]').forEach(e=>e.onclick=()=>{if(e.dataset.quickFilter==='discount')state.catalogOnlyDiscount=!state.catalogOnlyDiscount;if(e.dataset.quickFilter==='stock')state.catalogOnlyStock=!state.catalogOnlyStock;e.classList.toggle('active',e.dataset.quickFilter==='discount'?state.catalogOnlyDiscount:state.catalogOnlyStock);renderCatalogResults(state.route==='offers')});document.querySelector('[data-coupon]')?.addEventListener('click',()=>toast('Cupom validado para esta demonstração'));document.querySelector('[data-action="login"]')?.addEventListener('click',()=>toast('Login preparado para integração'))}
document.body.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='menu'){document.querySelector('#drawer').classList.add('open');document.querySelector('#drawer').setAttribute('aria-hidden','false');document.querySelector('#backdrop').classList.add('open');document.documentElement.classList.add('menu-open')}if(a.dataset.action==='close-menu')closePanels();if(a.dataset.action==='search'){document.querySelector('#search-panel').classList.add('open');document.querySelector('#search-panel').setAttribute('aria-hidden','false');setTimeout(()=>document.querySelector('#global-search').focus(),50)}if(a.dataset.action==='close-search')closePanels();if(a.dataset.action==='catalog-filter'){const panel=document.querySelector('#catalog-advanced');if(panel){if(!touchUI()){panel.hidden=!panel.hidden}else if(panel.hidden){panel.hidden=false;requestAnimationFrame(()=>panel.classList.add('open'))}else{panel.classList.remove('open');setTimeout(()=>{if(!panel.classList.contains('open'))panel.hidden=true},180)}}}if(a.dataset.action==='notify')toast('Você está em dia com as novidades')});
document.querySelector('#global-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();const hits=[...products.map(p=>({...p,type:'Produto'})),...services.map((s,i)=>({id:100+i,name:s.name,type:'Serviço'}))].filter(x=>x.name.toLowerCase().includes(q)).slice(0,8);document.querySelector('#search-results').innerHTML=q?(state.productsLoad==='loading'?'<div class="search-skeleton" aria-label="Carregando busca"><span></span><span></span><span></span></div>':hits.length?hits.map(x=>`<div class="search-hit" data-search-id="${x.id}" data-search-type="${x.type}"><span><small>${html(x.type)}</small><br><strong>${html(x.name)}</strong></span><b>›</b></div>`).join(''):'<div class="empty">Nenhum resultado encontrado.</div>'):'';document.querySelectorAll('[data-search-id]').forEach(h=>h.onclick=()=>{if(h.dataset.searchType==='Serviço')go('services');else{state.selected=+h.dataset.searchId;go('product')}})});
document.addEventListener('input',e=>{const field=e.target.closest('[data-checkout-field]');if(field)state.checkoutData[field.dataset.checkoutField]=field.value});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-checkout]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(state.checkoutBusy)return;if(button.dataset.checkout==='prev'){state.checkoutStep--;render();return}if(!validateCheckoutStep())return;if(state.checkoutStep===5){state.checkoutBusy=true;button.disabled=true;button.classList.add('is-loading');button.textContent='Confirmando...';try{await createOrder();state.checkoutStep=6;state.cart={};save();render()}catch(error){button.disabled=false;button.classList.remove('is-loading');button.textContent='Confirmar pedido';showCheckoutError('Não foi possível salvar o pedido. Tente novamente.')}finally{state.checkoutBusy=false}return}state.checkoutStep++;render()},true);
window.addEventListener('popstate',e=>{closePanels();const entry=e.state||{};state.route=entry.route||location.hash.slice(1)||'home';if(entry.selected!=null)state.selected=entry.selected;render();requestAnimationFrame(()=>window.scrollTo(0,Number(entry.scrollY)||0))});
state.route=location.hash.slice(1)||'home';if(!['home','catalog','offers','product','cart','checkout','services','orders','profile','favorites'].includes(state.route))state.route='home';history.replaceState({route:state.route,selected:state.selected,scrollY:0,depth:0},'',location.href);updateCart();render();loadStoreSettings();loadProducts();loadStorefrontCategories();loadStorefrontBanners();loadPublicServices();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){loadStoreSettings();loadStorefrontBanners();if(state.route==='services')loadPublicServices()}});setInterval(()=>{if(document.visibilityState==='visible'){loadStoreSettings();loadStorefrontBanners()}},60000)
